function toggleFullscreen(){
  if(!document.fullscreenElement){
    host.requestFullscreen().catch(()=>{});
  } else {
    document.exitFullscreen().catch(()=>{});
  }
}
const fsBtn = root.querySelector('#gms-fullscreen-btn');
fsBtn.addEventListener('click', toggleFullscreen);
document.addEventListener('fullscreenchange', () => {
  if (document.fullscreenElement) {
    fsBtn.textContent = '✕ Exit Fullscreen';
    fsBtn.title = 'Exit Fullscreen (F or Esc)';
  } else {
    fsBtn.textContent = '⛶ Fullscreen';
    fsBtn.title = 'Toggle Fullscreen Canvas (F)';
  }
});

window.addEventListener('keydown', e => {
  if (['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName) || e.target.isContentEditable) return;
  if (e.key === 'f' || e.key === 'F') {
    e.preventDefault();
    toggleFullscreen();
  } else if (e.key === 'CapsLock' || e.code === 'CapsLock') {
    if (typeof depDeselect === 'function' && (typeof depSelected !== 'undefined' && depSelected || typeof depCamera !== 'undefined' && depCamera)) {
      e.preventDefault();
      depDeselect(true);
      return;
    }
  } else if (e.key === 'Escape') {
    if (typeof depDeselect === 'function' && (typeof depSelected !== 'undefined' && depSelected || typeof depCamera !== 'undefined' && depCamera)) {
      depDeselect(true);
      return;
    } else if (typeof depReturnView === 'function' && typeof depCamera !== 'undefined' && depCamera) {
      depReturnView();
      return;
    }
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(()=>{});
    }
  }
});

