let lastFrame=0;
const camVelocity = { theta: 0, phi: 0, zoom: 0, panRight: 0, panForward: 0 };
window.__CAM_VELOCITY = camVelocity;

function animate(time){
  const dt=Math.min((time-lastFrame)/1000,.05);
  lastFrame=time;
  let needsDraw=false;
  if(motion){
    const a=1-Math.exp(-14*dt);
    camera.position.lerp(motion.p,a);
    controls.target.lerp(motion.t,a);
    if(camera.position.distanceTo(motion.p)<.0005&&controls.target.distanceTo(motion.t)<.0005){
      camera.position.copy(motion.p);
      controls.target.copy(motion.t);
      motion=null;
    }
    needsDraw=true;
  }
  if(Math.abs(camVelocity.theta) > 0.00005 || Math.abs(camVelocity.phi) > 0.00005 || Math.abs(camVelocity.zoom) > 0.00005){
    const offset = camera.position.clone().sub(controls.target);
    const spherical = new THREE.Spherical().setFromVector3(offset);
    spherical.theta += camVelocity.theta;
    spherical.phi = THREE.MathUtils.clamp(spherical.phi + camVelocity.phi, 0.06, Math.PI / 2 - 0.02);
    spherical.radius = THREE.MathUtils.clamp(spherical.radius * (1 + camVelocity.zoom), controls.minDistance, controls.maxDistance);
    offset.setFromSpherical(spherical);
    camera.position.copy(controls.target).add(offset);
    camera.lookAt(controls.target);
    
    // Smooth frame-rate independent deceleration / inertia
    const camDamp = Math.exp(-11 * dt);
    camVelocity.theta *= camDamp;
    camVelocity.phi *= camDamp;
    camVelocity.zoom *= camDamp;
    needsDraw = true;
  }
  if(Math.abs(camVelocity.panRight) > 0.0005 || Math.abs(camVelocity.panForward) > 0.0005){
    const forward = new THREE.Vector3();
    camera.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();
    const right = new THREE.Vector3();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
    
    const moveVec = new THREE.Vector3();
    moveVec.addScaledVector(right, camVelocity.panRight);
    moveVec.addScaledVector(forward, camVelocity.panForward);
    
    camera.position.add(moveVec);
    controls.target.add(moveVec);
    
    const panDamp = Math.exp(-11 * dt);
    camVelocity.panRight *= panDamp;
    camVelocity.panForward *= panDamp;
    needsDraw = true;
  }
  if(window.__DEP_TICK){
    try{
      if(window.__DEP_TICK(dt)) needsDraw = true;
    }catch(err){console.error('dep tick error',err);}
  }
  const changed=controls.update();
  if(changed||needsDraw)draw();
  requestAnimationFrame(animate);
}
requestAnimationFrame(animate);

